#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<std::vector<int>> constructGridLayout(int n, std::vector<std::vector<int>>& edges) {
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        std::vector<int> deg(n);
        int min_d = n;
        for (int i = 0; i < n; ++i) {
            deg[i] = adj[i].size();
            min_d = std::min(min_d, deg[i]);
        }

        int start = -1;
        for (int i = 0; i < n; ++i) {
            if (deg[i] == min_d) {
                start = i;
                break;
            }
        }

        std::vector<int> row = {start};
        std::vector<bool> visited(n, false);
        visited[start] = true;

        int curr = adj[start][0];
        for (int v : adj[start]) {
            if (deg[v] < deg[curr]) curr = v;
        }
        row.push_back(curr);
        visited[curr] = true;

        while (deg[curr] > min_d) {
            int nxt = -1;
            for (int v : adj[curr]) {
                if (!visited[v]) {
                    if (nxt == -1 || deg[v] < deg[nxt]) nxt = v;
                }
            }
            row.push_back(nxt);
            visited[nxt] = true;
            curr = nxt;
        }

        int cols = row.size();
        int rows = n / cols;
        std::vector<std::vector<int>> grid(rows, std::vector<int>(cols));
        grid[0] = row;

        for (int r = 1; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                int top = grid[r - 1][c];
                for (int v : adj[top]) {
                    if (!visited[v]) {
                        grid[r][c] = v;
                        visited[v] = true;
                        break;
                    }
                }
            }
        }
        return grid;
    }
};

import java.util.*;

class Solution {
    public int[][] constructGridLayout(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }

        int[] deg = new int[n];
        int minD = n;
        for (int i = 0; i < n; i++) {
            deg[i] = adj.get(i).size();
            minD = Math.min(minD, deg[i]);
        }

        int start = -1;
        for (int i = 0; i < n; i++) {
            if (deg[i] == minD) {
                start = i;
                break;
            }
        }

        List<Integer> row = new ArrayList<>();
        row.add(start);
        boolean[] visited = new boolean[n];
        visited[start] = true;

        int curr = adj.get(start).get(0);
        for (int v : adj.get(start)) {
            if (deg[v] < deg[curr]) curr = v;
        }
        row.add(curr);
        visited[curr] = true;

        while (deg[curr] > minD) {
            int nxt = -1;
            for (int v : adj.get(curr)) {
                if (!visited[v]) {
                    if (nxt == -1 || deg[v] < deg[nxt]) nxt = v;
                }
            }
            row.add(nxt);
            visited[nxt] = true;
            curr = nxt;
        }

        int cols = row.size();
        int rows = n / cols;
        int[][] grid = new int[rows][cols];
        for (int c = 0; c < cols; c++) grid[0][c] = row.get(c);

        for (int r = 1; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int top = grid[r - 1][c];
                for (int v : adj.get(top)) {
                    if (!visited[v]) {
                        grid[r][c] = v;
                        visited[v] = true;
                        break;
                    }
                }
            }
        }
        return grid;
    }
}

var constructGridLayout = function(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const deg = new Int32Array(n);
    let minD = n;
    for (let i = 0; i < n; i++) {
        deg[i] = adj[i].length;
        if (deg[i] < minD) minD = deg[i];
    }

    let start = -1;
    for (let i = 0; i < n; i++) {
        if (deg[i] === minD) {
            start = i;
            break;
        }
    }

    const row = [start];
    const visited = new Uint8Array(n);
    visited[start] = 1;

    let curr = adj[start][0];
    for (const v of adj[start]) {
        if (deg[v] < deg[curr]) curr = v;
    }
    row.push(curr);
    visited[curr] = 1;

    while (deg[curr] > minD) {
        let nxt = -1;
        for (const v of adj[curr]) {
            if (!visited[v]) {
                if (nxt === -1 || deg[v] < deg[nxt]) nxt = v;
            }
        }
        row.push(nxt);
        visited[nxt] = 1;
        curr = nxt;
    }

    const cols = row.length;
    const rows = Math.floor(n / cols);
    const grid = Array.from({ length: rows }, () => new Int32Array(cols));
    for (let c = 0; c < cols; c++) grid[0][c] = row[c];

    for (let r = 1; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            const top = grid[r - 1][c];
            for (const v of adj[top]) {
                if (!visited[v]) {
                    grid[r][c] = v;
                    visited[v] = 1;
                    break;
                }
            }
        }
    }
    return grid.map(r => Array.from(r));
};
